UPDATE t_workflow_action_template SET template_name = #{row.templateName}, description = #{row.description},
        config_json = #{row.configJson}, status = #{row.status}, version = version + 1, updated_by = #{row.updatedBy},
        update_time = #{row.updateTime}
        WHERE action_template_id = #{row.actionTemplateId} AND version = #{row.version}
